// Packaging-line simulator. Ticks every second, publishes every PUBLISH_INTERVAL s.
const F = global.get('factory');
const site = F.site, line = F.line;
const interval = F.interval;
const now = Date.now();
if (now - (context.get('last') || 0) < interval * 1000 - 100) {
    return null;
}
context.set('last', now);
F.chaosTick(now, node);

const DEFS = F.DEFS;
const STATE_CODE = { RUNNING: 0, DEGRADED: 1, STOPPED: 2, FAULT: 3, STARVED: 4 };
const machines = global.get('machines') || {};
const approach = (cur, target, k) => cur + (target - cur) * k;
const noise = (amp) => (Math.random() - 0.5) * amp;
const round = (v, d) => Math.round(v * 10 ** d) / 10 ** d;
const msgs = [];

for (const [id, d] of Object.entries(DEFS)) {
    const m = machines[id] || F.newMachine(id);
    const active = F.activeFaults(id);
    const has = (f) => active.includes(f);
    const special = {};

    // Upstream supply: a machine starves 15 s after its upstream stops producing.
    const up = d.upstream ? machines[d.upstream] : null;
    if (up && up.producing === false) {
        m.starvedSince = m.starvedSince || now;
    } else {
        m.starvedSince = null;
    }
    const starved = m.starvedSince && now - m.starvedSince > 15000;

    // Build-up signals.
    if (id === 'press-01') {
        m.pressure = has('hydraulic_leak')
            ? Math.max(60, m.pressure - 1.5 * interval + noise(0.8))
            : approach(m.pressure, 210, 0.15) + noise(0.8);
        special.pressure_bar = round(m.pressure, 1);
    }
    if (id === 'cnc-02') {
        m.tool_wear = Math.min(120, m.tool_wear + 0.01 * interval);
        m.scrap = approach(m.scrap, m.tool_wear < 60 ? 0.6 : 0.6 + (m.tool_wear - 60) * 0.25, 0.3) + noise(0.05);
        special.tool_wear_pct = round(m.tool_wear, 1);
        special.scrap_rate_pct = round(Math.max(0, m.scrap), 2);
    }
    if (id === 'robot-03') {
        m.misgrips = (m.misgrips || []).filter((t) => now - t < 120000);
        special.misgrips_2m = m.misgrips.length;
    }

    // Latched trips: cleared only by a "none" command for the machine.
    if (!m.tripped) {
        if (m.temperature >= 95) m.tripped = 'over-temperature trip';
        else if (m.vibration >= 11) m.tripped = 'vibration trip';
        else if (id === 'robot-03' && m.misgrips.length >= 3) m.tripped = 'safety stop: 3 misgrips in 2 min';
    }

    let state = 'RUNNING', reason = '';
    if (m.tripped) { state = 'FAULT'; reason = m.tripped; }
    else if (has('jam')) { state = 'STOPPED'; reason = 'conveyor jam'; }
    else if (id === 'press-01' && m.pressure < 140) { state = 'STOPPED'; reason = 'low hydraulic pressure'; }
    else if (id === 'cnc-02' && m.tool_wear >= 100) { state = 'STOPPED'; reason = 'tool change required'; }
    else if (starved) { state = 'STARVED'; reason = `waiting for ${d.upstream}`; }
    else {
        const issues = active.slice();
        if (id === 'press-01' && m.pressure < 170 && !issues.includes('hydraulic_leak')) issues.push('low pressure');
        if (id === 'cnc-02' && m.tool_wear >= 60) issues.push(`tool wear ${Math.round(m.tool_wear)}%`);
        if (id === 'robot-03' && m.misgrips.length > 0) issues.push(`${m.misgrips.length} misgrip(s)`);
        if (issues.length) { state = 'DEGRADED'; reason = issues.join(', '); }
    }

    let tT = d.temp, vT = d.vib, rT = d.rpm, pT = d.power, rate = d.rate;
    if (has('overheat')) { tT = d.temp + 50; pT = d.power * 1.3; }
    if (has('bearing')) { vT = d.vib + 12; tT = d.temp + 9; }
    const down = ['STOPPED', 'FAULT', 'STARVED'].includes(state);
    if (down) { rT = 0; pT = d.power * 0.12; rate = 0; }

    m.temperature = approach(m.temperature, tT, has('overheat') ? 0.05 : 0.12) + noise(0.6);
    m.vibration = Math.max(0, approach(m.vibration, vT, has('bearing') ? 0.05 : 0.2) + noise(0.3));
    m.rpm = Math.max(0, approach(m.rpm, rT, 0.4) + (rT ? noise(rT * 0.01) : 0));
    m.power_kw = Math.max(0, approach(m.power_kw, pT, 0.3) + noise(pT * 0.04));
    const good = id === 'cnc-02' ? 1 - Math.max(0, m.scrap) / 100 : 1;
    m.parts += rate * (interval / 60) * (0.9 + Math.random() * 0.2) * good;
    m.producing = !down;

    let health = 100;
    health -= Math.max(0, m.temperature - (d.temp + 8)) * 1.6;
    health -= Math.max(0, m.vibration - (d.vib + 1.5)) * 6;
    if (id === 'press-01') health -= Math.max(0, 195 - m.pressure) * 0.9;
    if (id === 'cnc-02') health -= Math.max(0, m.tool_wear - 40) * 0.8;
    if (id === 'robot-03') health -= m.misgrips.length * 15;
    if (state === 'STARVED') health = Math.min(health, 60);
    if (state === 'STOPPED') health = Math.min(health, 25);
    if (state === 'FAULT') health = Math.min(health, 5);

    m.state = state;
    machines[id] = m;
    msgs.push({
        topic: `factory/${site}/${line}/${id}/telemetry`,
        payload: Object.assign({
            ts: now, site, line, machine: id, type: d.type,
            state, state_code: STATE_CODE[state], reason,
            faults: active.join(',') || 'none',
            chaos: F.chaosOn(id),
            temperature: round(m.temperature, 1),
            vibration: round(m.vibration, 2),
            rpm: Math.round(m.rpm),
            power_kw: round(m.power_kw, 2),
            parts_total: Math.floor(m.parts),
            health: Math.round(Math.max(0, Math.min(100, health)))
        }, special)
    });
}
global.set('machines', machines);

const bad = msgs.filter((x) => x.payload.state !== 'RUNNING');
const chaos = F.chaosEnabled() ? ' | chaos ON' : '';
node.status(bad.length
    ? { fill: 'red', shape: 'dot', text: bad.map((x) => `${x.payload.machine} ${x.payload.state}`).join(', ') + chaos }
    : { fill: 'green', shape: 'dot', text: `3 machines RUNNING, every ${interval}s${chaos}` });
return [msgs];

