// Shared factory engine: machine models, fault catalog, commands, chaos mode,
// scenarios and the console. Stored in global context as "factory" and used by
// the simulator, the fault buttons, MQTT commands and the control-room API.
const site = env.get('FACTORY_SITE') || 'demo';
const line = env.get('FACTORY_LINE') || 'line-1';
const interval = Math.max(1, parseInt(env.get('PUBLISH_INTERVAL') || '2', 10));

// Nominal temperature (C), vibration (mm/s), rpm, power (kW), rate (parts/min).
// Each machine feeds the next one; a stopped upstream machine starves it.
const DEFS = {
    'press-01': { type: 'hydraulic_press', label: 'Hydraulic press', temp: 62, vib: 2.2, rpm: 30, power: 18, rate: 12,
        upstream: null, faults: { overheat: 'sustained', hydraulic_leak: 'sustained' } },
    'cnc-02': { type: 'cnc_mill', label: 'CNC mill', temp: 48, vib: 3.0, rpm: 9000, power: 11, rate: 10,
        upstream: 'press-01', faults: { bearing: 'sustained', tool_wear: 'cumulative' } },
    'robot-03': { type: 'packing_robot', label: 'Packing robot', temp: 41, vib: 1.4, rpm: 1500, power: 4.5, rate: 10,
        upstream: 'cnc-02', faults: { jam: 'sustained', misgrip: 'cumulative' } }
};
const FAULT_INFO = {
    overheat: 'cooling failure: temperature climbs, warning at 85 C, trips at 95 C (~40 s)',
    hydraulic_leak: 'pressure bleeds from 210 bar, warning below 170, press stops below 140 (~50 s); cnc-02 and robot-03 starve',
    bearing: 'spindle bearing wear: vibration climbs, warning at 7, trips at 11 mm/s (~40 s)',
    tool_wear: 'cumulative: each hit adds 35% tool wear; scrap rises above 60%; the 3rd hit stops the mill for a tool change',
    jam: 'conveyor jam: the robot stops immediately',
    misgrip: 'cumulative: each hit drops a part; 3 misgrips within 2 minutes trip a safety stop'
};
const SCENARIOS = {
    heatwave: { info: 'overheat on press-01 and bearing wear on cnc-02', steps: [[0, 'press-01', 'overheat'], [0, 'cnc-02', 'bearing']] },
    'leak-cascade': { info: 'hydraulic leak stops the press, then the line starves downstream', steps: [[0, 'press-01', 'hydraulic_leak']] },
    'worn-tools': { info: 'three tool-wear hits 8 s apart: scrap climbs, then the mill stops', steps: [[0, 'cnc-02', 'tool_wear'], [8, 'cnc-02', 'tool_wear'], [16, 'cnc-02', 'tool_wear']] },
    butterfingers: { info: 'three misgrips 6 s apart: warnings, then a safety stop', steps: [[0, 'robot-03', 'misgrip'], [6, 'robot-03', 'misgrip'], [12, 'robot-03', 'misgrip']] },
    meltdown: { info: 'every sustained fault at once, plus chaos mode', steps: [[0, 'press-01', 'overheat'], [0, 'cnc-02', 'bearing'], [0, 'robot-03', 'jam']], chaos: true },
    'all-clear': { info: 'clear every fault on this line (chaos mode unchanged)', steps: [[0, 'all', 'none']] }
};

function newMachine(id) {
    const d = DEFS[id];
    return { temperature: d.temp, vibration: d.vib, rpm: d.rpm, power_kw: d.power, parts: 0,
        pressure: 210, tool_wear: 5, scrap: 0.5, misgrips: [], tripped: null, producing: true, state: 'RUNNING' };
}

function machinesState() {
    const ms = global.get('machines') || {};
    for (const id of Object.keys(DEFS)) ms[id] = ms[id] || newMachine(id);
    global.set('machines', ms);
    return ms;
}

function activeFaults(id) {
    const manual = (global.get('faults') || {})[id] || {};
    const chaos = ((global.get('chaosFaults') || {})[id] || {}).faults || {};
    return Object.keys(Object.assign({}, manual, chaos));
}

function chaosEnabled() { return !!global.get('chaosEnabled'); }
function chaosOn(id) { return !!(global.get('chaosFaults') || {})[id]; }

function log(text, source) {
    const feed = global.get('consoleLog') || [];
    feed.unshift({ ts: Date.now(), text, source: source || 'system' });
    global.set('consoleLog', feed.slice(0, 50));
}

// Apply {machine, fault}; source is 'manual' or 'chaos'.
function applyCommand(machine, fault, source) {
    fault = String(fault || 'none').toLowerCase();
    machine = String(machine || 'all');
    const ids = machine === 'all' ? Object.keys(DEFS) : [machine];
    if (machine !== 'all' && !DEFS[machine]) {
        return { ok: false, error: `unknown machine '${machine}'. Machines: ${Object.keys(DEFS).join(', ')}, all` };
    }
    const targets = fault === 'none' ? ids : ids.filter((id) => DEFS[id].faults[fault]);
    if (!targets.length) {
        const valid = machine === 'all' ? Object.keys(FAULT_INFO) : Object.keys(DEFS[machine].faults);
        return { ok: false, error: `fault '${fault}' does not apply to ${machine}. Valid: ${valid.join(', ')}, none` };
    }
    const ms = machinesState();
    const manual = global.get('faults') || {};
    const chaos = global.get('chaosFaults') || {};
    const now = Date.now();
    for (const id of targets) {
        const m = ms[id];
        if (fault === 'none') {
            delete manual[id];
            delete chaos[id];
            m.tripped = null;
            m.misgrips = [];
            if (m.tool_wear >= 60) m.tool_wear = 5;
            continue;
        }
        const kind = DEFS[id].faults[fault];
        if (kind === 'cumulative') {
            if (fault === 'tool_wear') m.tool_wear = Math.min(120, m.tool_wear + 35);
            if (fault === 'misgrip') m.misgrips.push(now);
        } else if (source === 'chaos') {
            chaos[id] = chaos[id] || { faults: {}, repairAt: 0 };
            chaos[id].faults[fault] = true;
        } else {
            manual[id] = manual[id] || {};
            manual[id][fault] = true;
        }
        if (source === 'chaos') {
            chaos[id] = chaos[id] || { faults: {}, repairAt: 0 };
            chaos[id].repairAt = now + 120000;
        }
    }
    global.set('faults', manual);
    global.set('chaosFaults', chaos);
    global.set('machines', ms);
    const text = `${source === 'chaos' ? 'chaos' : 'fault'}: ${targets.join(', ')} -> ${fault}`;
    log(text, source);
    return { ok: true, machines: targets, fault, source };
}

function setChaos(enabled) {
    global.set('chaosEnabled', !!enabled);
    global.set('chaosNext', Date.now() + 20000);
    log(`chaos mode ${enabled ? 'ON' : 'OFF'}`, 'manual');
    return { ok: true, chaos: !!enabled };
}

// Called by the simulator every tick: random faults while chaos is on, and
// self-repair of chaos-hit machines after 2 minutes (manual faults untouched).
function chaosTick(now, node) {
    const chaos = global.get('chaosFaults') || {};
    const manual = global.get('faults') || {};
    for (const [id, c] of Object.entries(chaos)) {
        if (now >= c.repairAt) {
            delete chaos[id];
            global.set('chaosFaults', chaos);
            if (!manual[id]) {
                const ms = machinesState();
                ms[id].tripped = null;
                ms[id].misgrips = [];
                if (ms[id].tool_wear >= 60) ms[id].tool_wear = 5;
                global.set('machines', ms);
            }
            log(`chaos: ${id} repaired`, 'chaos');
            node.log(`chaos: ${id} repaired`);
        }
    }
    if (!chaosEnabled()) return;
    if (now < (global.get('chaosNext') || 0)) return;
    const options = [];
    for (const [id, d] of Object.entries(DEFS)) for (const f of Object.keys(d.faults)) options.push([id, f]);
    const [id, f] = options[Math.floor(Math.random() * options.length)];
    applyCommand(id, f, 'chaos');
    node.log(`chaos: ${f} on ${id}`);
    global.set('chaosNext', now + (45 + Math.random() * 75) * 1000);
}

function runScenario(name, node) {
    const s = SCENARIOS[name];
    if (!s) return { ok: false, error: `unknown scenario '${name}'. Scenarios: ${Object.keys(SCENARIOS).join(', ')}` };
    if (s.chaos) setChaos(true);
    for (const [delay, machine, fault] of s.steps) {
        if (delay === 0) applyCommand(machine, fault, 'manual');
        else setTimeout(() => applyCommand(machine, fault, 'manual'), delay * 1000);
    }
    log(`scenario ${name}: ${s.info}`, 'manual');
    return { ok: true, scenario: name, info: s.info };
}

// Line status for this instance plus every line seen on MQTT (joined factories).
function status() {
    return {
        site, line, interval,
        chaos: chaosEnabled(),
        faults: global.get('faults') || {},
        chaos_faults: global.get('chaosFaults') || {},
        machines: global.get('machines') || {},
        lines: global.get('lines') || {},
        active_alerts: Object.values(global.get('activeAlerts') || {}),
        recent_alerts: (global.get('recentAlerts') || []).slice(0, 20),
        console_log: (global.get('consoleLog') || []).slice(0, 20),
        catalog: Object.fromEntries(Object.entries(DEFS).map(([id, d]) =>
            [id, { label: d.label, upstream: d.upstream, faults: Object.keys(d.faults) }])),
        fault_info: FAULT_INFO,
        scenarios: Object.fromEntries(Object.entries(SCENARIOS).map(([k, v]) => [k, v.info])),
        links: global.get('links') || {}
    };
}

global.set('factory', {
    site, line, interval, DEFS, FAULT_INFO, SCENARIOS,
    newMachine, activeFaults, applyCommand, setChaos, chaosTick, chaosEnabled, chaosOn, runScenario, status, log
});
global.set('chaosEnabled', String(env.get('AUTO_CHAOS')).toLowerCase() === 'true');
global.set('chaosNext', Date.now() + 30000);
global.set('links', {
    grafana: env.get('GRAFANA_URL') || '',
    mqttx: env.get('MQTTX_URL') || '',
    influxdb: env.get('INFLUXDB_URL') || '',
    mqtt: env.get('MQTT_URL') || '',
    mqtt_ws: env.get('MQTT_WS_URL') || ''
});
machinesState();

