// Editor buttons: {machine, fault} or {chaos: true|false} or {scenario: name}
const F = global.get('factory');
const p = msg.payload || {};
let r;
if (p.scenario) r = F.runScenario(p.scenario);
else if (typeof p.chaos === 'boolean') r = F.setChaos(p.chaos);
else r = F.applyCommand(p.machine, p.fault, 'manual');
const active = Object.keys(global.get('faults') || {}).length + Object.keys(global.get('chaosFaults') || {}).length;
node.status({ fill: active ? 'red' : 'green', shape: active ? 'ring' : 'dot',
    text: `${active} machine(s) with faults, chaos ${F.chaosEnabled() ? 'ON' : 'off'}` });
msg.payload = r;
return msg;

// factory/<site>/<line>/<machine>/cmd  {"fault":"overheat"} or "overheat"
// factory/<site>/<line>/chaos          on | off
// Only commands addressed to this line are applied (joined factories share topics).
const F = global.get('factory');
const [, s, l, machine, leaf] = msg.topic.split('/');
if (s !== F.site || l !== F.line) return null;
let r;
if (machine === 'chaos') {
    const v = String(typeof msg.payload === 'object' ? msg.payload.enabled : msg.payload).toLowerCase();
    r = F.setChaos(v === 'on' || v === 'true');
} else if (leaf === 'cmd') {
    const f = (msg.payload && typeof msg.payload === 'object') ? msg.payload.fault : String(msg.payload);
    r = F.applyCommand(machine, f, 'manual');
} else {
    return null;
}
if (!r.ok) node.warn(`rejected MQTT command on ${msg.topic}: ${r.error}`);
node.status({ fill: r.ok ? 'green' : 'red', shape: 'dot', text: `${msg.topic.split('/').slice(3).join('/')} ${r.ok ? 'ok' : 'rejected'}` });
msg.payload = r;
return msg;

// Control-room API (basic auth via httpNodeAuth). Output 1: HTTP response.
// Output 2: MQTT publish (commands for other factories, console "pub").
const F = global.get('factory');
const path = (msg.req && msg.req.path) || '';
const body = (msg.payload && typeof msg.payload === 'object') ? msg.payload : {};
const out = [];
const reply = (code, payload) => {
    msg.statusCode = code;
    msg.payload = payload;
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
    return [msg, out.length ? out : null];
};
const isLocal = (s, l) => (!s || s === F.site) && (!l || l === F.line);

// Route a fault to this line, or over MQTT to a joined factory's line.
function fault(siteArg, lineArg, machine, f) {
    if (isLocal(siteArg, lineArg)) return F.applyCommand(machine, f, 'manual');
    const machines = machine === 'all' ? Object.keys(F.DEFS) : [machine];
    for (const m of machines) {
        out.push({ topic: `factory/${siteArg}/${lineArg}/${m}/cmd`, payload: JSON.stringify({ fault: f }) });
    }
    F.log(`fault: ${siteArg}/${lineArg} ${machine} -> ${f} (sent over MQTT)`, 'manual');
    return { ok: true, routed: 'mqtt', site: siteArg, line: lineArg, machine, fault: f };
}

function chaos(siteArg, lineArg, enabled) {
    if (isLocal(siteArg, lineArg)) return F.setChaos(enabled);
    out.push({ topic: `factory/${siteArg}/${lineArg}/chaos`, payload: enabled ? 'on' : 'off' });
    return { ok: true, routed: 'mqtt', chaos: enabled };
}

const HELP = [
    'Commands:',
    '  status                         line state, faults and active alerts',
    '  lines                          every line seen on MQTT (joined factories)',
    '  faults                         fault catalog per machine',
    '  inject <machine> <fault> [site/line]   e.g. inject press-01 overheat',
    '  clear [machine|all] [site/line]        clear faults (default: all)',
    '  chaos on|off [site/line]       random faults every 45-120 s, self-repair after 2 min',
    '  scenario <name>                ' + Object.keys(F.SCENARIOS).join(' | '),
    '  pub <topic> <payload>          publish an MQTT message (topic must start with factory/)',
    '  help'
];

function consoleCmd(text) {
    const parts = String(text || '').trim().split(/\s+/).filter(Boolean);
    const cmd = (parts.shift() || 'help').toLowerCase();
    const target = (arg) => {
        if (!arg || !arg.includes('/')) return [null, null];
        const [s, l] = arg.split('/');
        return [s, l];
    };
    const fmt = (r) => r.ok ? [`ok: ${JSON.stringify(r)}`] : [`error: ${r.error}`];
    if (cmd === 'help') return HELP;
    if (cmd === 'status') {
        const st = F.status();
        const lines = [`line ${st.site}/${st.line}  chaos=${st.chaos ? 'ON' : 'off'}  interval=${st.interval}s`];
        for (const [id, m] of Object.entries(st.machines)) {
            const faults = F.activeFaults(id).join(',') || 'none';
            lines.push(`  ${id.padEnd(9)} ${String(m.state).padEnd(9)} T=${m.temperature.toFixed(1)}C V=${m.vibration.toFixed(1)} faults=${faults}`);
        }
        lines.push(`active alerts: ${st.active_alerts.length}`);
        for (const a of st.active_alerts.slice(0, 8)) lines.push(`  [${a.severity}] ${a.site}/${a.line} ${a.message}`);
        return lines;
    }
    if (cmd === 'lines') {
        const lines = [];
        for (const [key, l] of Object.entries(F.status().lines)) {
            const states = Object.values(l.machines).map((t) => `${t.machine}:${t.state}`).join('  ');
            lines.push(`${key.padEnd(24)} ${states}  (${Math.round((Date.now() - l.updated) / 1000)}s ago)`);
        }
        return lines.length ? lines : ['no telemetry seen yet'];
    }
    if (cmd === 'faults') {
        const lines = [];
        for (const [id, d] of Object.entries(F.DEFS)) {
            lines.push(`${id} (${d.label}${d.upstream ? ', fed by ' + d.upstream : ''})`);
            for (const f of Object.keys(d.faults)) lines.push(`  ${f.padEnd(15)} ${F.FAULT_INFO[f]}`);
        }
        return lines;
    }
    if (cmd === 'inject') {
        if (parts.length < 2) return ['usage: inject <machine> <fault> [site/line]'];
        const [s, l] = target(parts[2]);
        return fmt(fault(s || F.site, l || F.line, parts[0], parts[1]));
    }
    if (cmd === 'clear') {
        const machine = parts[0] && !parts[0].includes('/') ? parts[0] : 'all';
        const [s, l] = target(parts.find((p) => p.includes('/')));
        return fmt(fault(s || F.site, l || F.line, machine, 'none'));
    }
    if (cmd === 'chaos') {
        const on = (parts[0] || '').toLowerCase();
        if (!['on', 'off'].includes(on)) return ['usage: chaos on|off [site/line]'];
        const [s, l] = target(parts[1]);
        return fmt(chaos(s || F.site, l || F.line, on === 'on'));
    }
    if (cmd === 'scenario') {
        if (!parts[0]) return ['scenarios:'].concat(Object.entries(F.SCENARIOS).map(([k, v]) => `  ${k.padEnd(14)} ${v.info}`));
        return fmt(F.runScenario(parts[0]));
    }
    if (cmd === 'pub') {
        const topic = parts.shift();
        if (!topic || !topic.startsWith('factory/')) return ['usage: pub <topic starting with factory/> <payload>'];
        out.push({ topic, payload: parts.join(' ') });
        F.log(`pub ${topic} ${parts.join(' ')}`, 'manual');
        return [`published to ${topic}`];
    }
    return [`unknown command '${cmd}'. Type help.`];
}

if (path.endsWith('/status')) return reply(200, F.status());
if (path.endsWith('/feed')) {
    const since = parseInt((msg.req.query || {}).since || '0', 10);
    const feed = global.get('feed') || { seq: 0, items: [] };
    return reply(200, { seq: feed.seq, items: feed.items.filter((i) => i.seq > since).slice(-150) });
}
if (path.endsWith('/fault')) {
    const r = fault(body.site || F.site, body.line || F.line, body.machine || 'all', body.fault || 'none');
    return reply(r.ok ? 200 : 400, r);
}
if (path.endsWith('/chaos')) {
    return reply(200, chaos(body.site || F.site, body.line || F.line, body.enabled === true || body.enabled === 'on'));
}
if (path.endsWith('/scenario')) {
    const r = F.runScenario(String(body.name || ''));
    return reply(r.ok ? 200 : 400, r);
}
if (path.endsWith('/console')) {
    F.log(`$ ${body.command || ''}`, 'console');
    return reply(200, { output: consoleCmd(body.command) });
}
return reply(404, { ok: false, error: `unknown endpoint ${path}` });

// Edge-triggered alert rules for every line seen on MQTT (this factory and any
// joined factory). Emits an alert when a rule's severity changes and a
// 'resolved' event when it returns to normal; misgrips raise one event each.
const t = msg.payload;
// Telemetry also arrives from joined factories: accept only well-formed
// messages (they are rendered in the control room and written to InfluxDB).
const ID = /^[a-z0-9][a-z0-9-]{0,31}$/;
const STATES = ['RUNNING', 'DEGRADED', 'STOPPED', 'FAULT', 'STARVED'];
const parts = String(msg.topic || '').split('/');
if (!t || typeof t !== 'object' || !ID.test(t.site) || !ID.test(t.line) || !ID.test(t.machine)
    || !STATES.includes(t.state) || !Number.isSafeInteger(t.ts) || t.ts <= 0 || parts[1] !== t.site || parts[2] !== t.line || parts[3] !== t.machine
    || !['temperature', 'vibration', 'rpm', 'power_kw', 'parts_total', 'health', 'state_code'].every((k) => Number.isFinite(t[k]))) {
    const n = (context.get('rejected') || 0) + 1;
    context.set('rejected', n);
    if (n === 1 || n % 100 === 0) node.warn(`dropped malformed telemetry on ${msg.topic} (${n} so far)`);
    return null;
}
t.reason = String(t.reason || '').slice(0, 120);
t.faults = String(t.faults || 'none').replace(/[^a-z_,]/g, '').slice(0, 80);
t.type = String(t.type || '').replace(/[^a-z_]/g, '').slice(0, 32);
t.chaos = t.chaos === true;
const RULES = [
    { rule: 'temperature', field: 'temperature', unit: 'C', dir: 'high', warn: 85, crit: 95 },
    { rule: 'vibration', field: 'vibration', unit: 'mm/s', dir: 'high', warn: 7, crit: 11 },
    { rule: 'pressure', field: 'pressure_bar', unit: 'bar', dir: 'low', warn: 170, crit: 140 },
    { rule: 'tool_wear', field: 'tool_wear_pct', unit: '%', dir: 'high', warn: 60, crit: 90 },
    { rule: 'scrap', field: 'scrap_rate_pct', unit: '%', dir: 'high', warn: 5, crit: 10 }
];
const STATE_SEVERITY = { FAULT: 'critical', STOPPED: 'warning', STARVED: 'info' };
const base = `${t.site}/${t.line}/${t.machine}`;
const levels = context.get('levels') || {};
const active = global.get('activeAlerts') || {};
const recent = global.get('recentAlerts') || [];
const out = [];

function emit(rule, severity, value, message, status) {
    const key = `${base}/${rule}`;
    const alert = { ts: t.ts, site: t.site, line: t.line, machine: t.machine, rule, severity, value, message, status };
    if (status === 'active') active[key] = alert;
    else if (status === 'resolved') delete active[key];
    recent.unshift(alert);
    out.push(alert);
}

for (const r of RULES) {
    if (typeof t[r.field] !== 'number') continue;
    const v = t[r.field];
    const over = (lim) => r.dir === 'high' ? v >= lim : v <= lim;
    const level = over(r.crit) ? 'critical' : over(r.warn) ? 'warning' : 'ok';
    const key = `${base}/${r.rule}`;
    const prev = levels[key] || 'ok';
    if (level === prev) continue;
    if (level === 'ok') {
        emit(r.rule, 'info', v, `${t.machine} ${r.rule} back to normal (${v} ${r.unit})`, 'resolved');
    } else {
        const limit = level === 'critical' ? r.crit : r.warn;
        const word = r.dir === 'high' ? 'above' : 'below';
        emit(r.rule, level, v, `${t.machine} ${r.rule} ${v} ${r.unit} ${word} ${level} limit ${limit} ${r.unit}`, 'active');
    }
    levels[key] = level;
}

if (typeof t.misgrips_2m === 'number') {
    const key = `${base}/misgrips`;
    const prev = levels[key] || 0;
    if (t.misgrips_2m > prev) {
        emit('misgrip', 'warning', t.misgrips_2m,
            `${t.machine} misgrip: ${t.misgrips_2m} in the last 2 min (3 trips a safety stop)`, 'event');
    }
    levels[key] = t.misgrips_2m;
}

const sKey = `${base}/state`;
const prevState = levels[sKey] || 'RUNNING';
const norm = t.state === 'DEGRADED' ? 'RUNNING' : t.state;
if (norm !== prevState) {
    if (norm === 'RUNNING') emit('state', 'info', t.state_code, `${t.machine} running again`, 'resolved');
    else emit('state', STATE_SEVERITY[norm] || 'warning', t.state_code, `${t.machine} ${norm}: ${t.reason}`, 'active');
    levels[sKey] = norm;
}

context.set('levels', levels);
global.set('activeAlerts', active);
global.set('recentAlerts', recent.slice(0, 100));

// Latest telemetry of every line, for the control room and the console.
const lines = global.get('lines') || {};
const lk = `${t.site}/${t.line}`;
lines[lk] = lines[lk] || { site: t.site, line: t.line, machines: {} };
lines[lk].machines[t.machine] = t;
lines[lk].updated = Date.now();
global.set('lines', lines);

if (out.length) {
    const crit = out.filter((a) => a.severity === 'critical').length;
    node.status({ fill: crit ? 'red' : 'yellow', shape: 'dot', text: out[out.length - 1].message });
}
const alertMsgs = out.map((a) => ({ topic: `factory/${t.site}/${t.line}/alerts`, payload: a }));
const toStore = [{ kind: 'telemetry', payload: t }].concat(out.map((a) => ({ kind: 'alert', payload: a })));
return [alertMsgs, toStore];

// Telemetry, alerts and pipeline stats -> InfluxDB 2 line protocol (HTTP write API).
const tag = (s) => String(s).replace(/[\r\n]/g, '').replace(/[ ,=]/g, '\\$&');
const str = (s) => '"' + String(s).replace(/[\r\n]/g, ' ').replace(/["\\]/g, '\\$&') + '"';
const p = msg.payload;
// Defense in depth: every number is coerced, so nothing but digits reaches the
// field values and timestamp.
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
const int = (v) => Math.round(num(v));
const ts = Number.isSafeInteger(Number(p.ts)) && Number(p.ts) > 0 ? Number(p.ts) : Date.now();
let lp;
if (msg.kind === 'raw') {
    lp = p;
} else if (msg.kind === 'alert') {
    lp = `alerts,site=${tag(p.site)},line=${tag(p.line)},machine=${tag(p.machine)},rule=${tag(p.rule)},severity=${tag(p.severity)}`
        + ` message=${str(p.message)},status=${str(p.status)},value=${num(p.value)},active=${p.status === 'resolved' ? 0 : 1}i ${ts}`;
} else {
    const fields = [
        `temperature=${num(p.temperature)}`, `vibration=${num(p.vibration)}`, `rpm=${int(p.rpm)}i`, `power_kw=${num(p.power_kw)}`,
        `parts_total=${int(p.parts_total)}i`, `health=${int(p.health)}i`, `state_code=${int(p.state_code)}i`,
        `state=${str(p.state)}`, `reason=${str(p.reason || '')}`, `faults=${str(p.faults || 'none')}`
    ];
    for (const f of ['pressure_bar', 'tool_wear_pct', 'scrap_rate_pct']) {
        if (Number.isFinite(p[f])) fields.push(`${f}=${num(p[f])}`);
    }
    if (Number.isFinite(p.misgrips_2m)) fields.push(`misgrips_2m=${int(p.misgrips_2m)}i`);
    lp = `machine_telemetry,site=${tag(p.site)},line=${tag(p.line)},machine=${tag(p.machine)},type=${tag(p.type)} ${fields.join(',')} ${ts}`;
}
const org = encodeURIComponent(env.get('INFLUX_ORG') || 'iot-factory');
const bucket = encodeURIComponent(env.get('INFLUX_BUCKET') || 'telemetry');
msg.method = 'POST';
msg.url = `http://influxdb:8086/api/v2/write?org=${org}&bucket=${bucket}&precision=ms`;
msg.headers = {
    Authorization: 'Token ' + global.get('influxToken'),
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = lp;
return msg;

// Count writes; report failures at most once a minute so the log stays readable.
const ok = msg.statusCode >= 200 && msg.statusCode < 300;
const s = global.get('pipelineStats') || { ok: 0, failed: 0, lastError: 0 };
if (ok) {
    s.ok += 1;
} else {
    s.failed += 1;
    if (Date.now() - s.lastError > 60000) {
        s.lastError = Date.now();
        node.error(`InfluxDB write failed (HTTP ${msg.statusCode || 'no response'}): ${String(msg.payload).slice(0, 200)}`, msg);
    }
}
global.set('pipelineStats', s);
node.status({ fill: s.failed ? 'red' : 'green', shape: 'dot', text: `written ${s.ok}, failed ${s.failed}` });
return null;

// Every 10 s: pipeline health for the Grafana and InfluxDB dashboards.
const F = global.get('factory');
const tag = (s) => String(s).replace(/[ ,=]/g, '\\$&');
const s = global.get('pipelineStats') || { ok: 0, failed: 0 };
const b = global.get('brokerStats') || {};
const c = global.get('mqttCounts') || {};
const lines = global.get('lines') || {};
const now = Date.now();
const recent = Object.values(lines).filter((l) => now - l.updated < 30000).length;
const t = `site=${tag(F.site)},line=${tag(F.line)}`;
const n = (v) => Math.round(Number(v) || 0);
const lp = [
    `pipeline,${t} influx_writes_ok=${n(s.ok)}i,influx_writes_failed=${n(s.failed)}i,`
        + `mqtt_telemetry=${n(c.telemetry)}i,mqtt_alerts=${n(c.alert)}i,mqtt_commands=${n(c.command)}i,lines_reporting=${recent}i ${now}`,
    `broker,${t} clients_connected=${n(b['clients/connected'])}i,messages_received=${n(b['messages/received'])}i,`
        + `messages_sent=${n(b['messages/sent'])}i,load_received_1min=${Number(b['load/messages/received/1min']) || 0} ${now}`
].join('\n');
node.status({ fill: s.failed ? 'red' : 'green', shape: 'dot', text: `writes ok ${s.ok} / failed ${s.failed}, ${recent} line(s)` });
return { kind: 'raw', payload: lp };

// Mosquitto $SYS statistics (published every 10 s by the broker).
const stats = global.get('brokerStats') || {};
const key = msg.topic.replace('$SYS/broker/', '');
const value = parseFloat(String(msg.payload));
if (!Number.isNaN(value)) stats[key] = value;
global.set('brokerStats', stats);
return null;

// Ring buffer of recent MQTT traffic for the control room's live feed.
const feed = global.get('feed') || { seq: 0, items: [] };
const kind = /\/alerts$/.test(msg.topic) ? 'alert'
    : /\/cmd$|\/chaos$/.test(msg.topic) ? 'command'
    : /\/telemetry$/.test(msg.topic) ? 'telemetry' : 'other';
let payload = msg.payload;
if (Buffer.isBuffer(payload)) payload = payload.toString();
if (typeof payload === 'object') payload = JSON.stringify(payload);
feed.seq += 1;
feed.items.push({ seq: feed.seq, ts: Date.now(), topic: msg.topic, kind, payload: String(payload).slice(0, 600) });
if (feed.items.length > 400) feed.items.splice(0, feed.items.length - 400);
global.set('feed', feed);
const counts = global.get('mqttCounts') || {};
counts[kind] = (counts[kind] || 0) + 1;
global.set('mqttCounts', counts);
return null;
